219	// 6A: Inactive — PATH activation
220	fn handle_inactive(
221	    requirement: &str,
222	    binary_path: &Path,
223	    activation_hint: &str,
224	    checker: &mut GapChecker<'_>,
225	    ctx: &InstallerContext<'_>,
226	) -> Outcome {
227	    if let Some(parent) = binary_path.parent() {
228	        (ctx.prepend_path)(parent);
229	        checker.invalidate(requirement);
230	        Outcome::Resolved
231	    } else {
232	        Outcome::Skip {
233	            reason: format!("'{}' activation failed. {}", requirement, activation_hint),
234	        }
235	    }
236	}
