30	impl<'a> WorkflowRunner<'a> {
31	    /// Run a workflow with full interactive UI support.
32	    ///
33	    /// This is the primary execution entry point for interactive use. It manages
34	    /// the workflow lifecycle: building the execution plan, iterating over steps,
35	    /// updating the progress bar, tracking workflow state, and recording results.
36	    ///
37	    /// Step-level concerns (check evaluation, prompts, execution, recovery) are
38	    /// delegated to [`StepManager`].
39	    #[allow(clippy::too_many_arguments)]
40	    pub fn run_with_ui(
41	        &mut self,
42	        options: &RunOptions,
43	        context: &InterpolationContext,
44	        base_env: &HashMap<String, String>,
45	        process_env: &HashMap<String, String>,
46	        project_root: &Path,
47	        workflow_non_interactive: bool,
48	        step_overrides: &HashMap<String, StepOverride>,
49	        mut gap_checker: Option<&mut GapChecker<'_>>,
50	        state: Option<&mut StateStore>,
51	        satisfaction_cache: &mut SatisfactionCache,
52	        ui: &mut dyn UserInterface,
53	        workflow_display: &mut dyn WorkflowDisplay,
54	        event_bus: &mut EventBus,
55	    ) -> Result<WorkflowResult> {
56	        let start = Instant::now();
57	        let workflow_name = options.workflow.as_deref().unwrap_or("default");
58	        let mut context = context.clone();
59	
60	        // Topological sort: compute execution order from the dependency graph.
61	        let graph = self.build_graph(workflow_name)?;
62	        let workflow_steps = &self.config.workflows[workflow_name].steps;
63	        // Pre-filter: remove steps excluded by --skip flags or only_environments mismatch.
64	        let plan = build_execution_plan(&graph, workflow_steps, options, &self.steps)?;
65	
66	        let total = plan.steps_to_run.len();
67	        let theme = BivvyTheme::new();
68	
69	        // Emit workflow started
70	        event_bus.emit(&BivvyEvent::WorkflowStarted {
71	            name: workflow_name.to_string(),
72	            step_count: total,
73	        });
74	
75	        // Report pre-filtered steps before the loop begins.
76	        for skip_name in &plan.flag_skipped {
77	            event_bus.emit(&BivvyEvent::StepFilteredOut {
78	                name: skip_name.clone(),
79	                reason: "skip_flag".to_string(),
80	            });
81	            event_bus.emit(&BivvyEvent::StepOutcome {
82	                name: skip_name.clone(),
83	                outcome: StepOutcomeKind::FilteredOut,
84	                detail: Some("skip_flag".to_string()),
85	                duration_ms: None,
86	            });
87	            ui.message(&format!(
88	                "    {}",
89	                theme.format_skipped(&format!("{} skipped", skip_name))
90	            ));
91	        }
92	        for skip_name in &plan.env_skipped {
93	            event_bus.emit(&BivvyEvent::StepFilteredOut {
94	                name: skip_name.clone(),
95	                reason: "environment".to_string(),
96	            });
97	            let env_label = options.active_environment.as_deref().unwrap_or("unknown");
98	            event_bus.emit(&BivvyEvent::StepOutcome {
99	                name: skip_name.clone(),
100	                outcome: StepOutcomeKind::FilteredOut,
101	                detail: Some(format!("not in {} environment", env_label)),
102	                duration_ms: None,
103	            });
104	            ui.message(&format!(
105	                "    {}",
106	                theme.format_skipped(&format!(
107	                    "{} skipped (not in {} environment)",
108	                    skip_name, env_label
109	                ))
110	            ));
111	        }
112	
113	        let interactive = ui.is_interactive() && !workflow_non_interactive;
114	
115	        let mut results = Vec::new();
116	        let mut all_success = true;
117	        let mut failed_steps: HashSet<String> = HashSet::new();
118	        let mut user_skipped_steps: HashSet<String> = HashSet::new();
119	        let mut satisfied_steps: HashSet<String> = HashSet::new();
120	        let mut named_check_results: HashMap<String, CheckResult> = HashMap::new();
121	        let mut workflow_aborted = false;
122	
123	        // Initialize the persistent progress bar (pinned at terminal bottom).
124	        workflow_display.start_progress(total);
125	
126	        for (index, step_name) in plan.steps_to_run.iter().enumerate() {
127	            let step =
128	                &self
129	                    .steps
130	                    .get(step_name)
131	                    .ok_or_else(|| BivvyError::ConfigValidationError {
132	                        message: format!("Step '{}' not found in resolved steps", step_name),
133	                    })?;
134	
135	            // Update progress bar immediately — before execution, so the user
136	            // sees "Step N/M" the moment iteration reaches this step.
137	            workflow_display.update_progress(index + 1, total, start.elapsed());
138	
139	            // Hand off to the step display for this iteration.
140	            let mut step_display = workflow_display.begin_step(index, total);
141	
142	            // Create StepManager and delegate step-level execution
143	            let step_mgr = StepManager::new(step, step_name, index, total, &theme);
144	
145	            let exec_opts = StepExecutionOptions {
146	                dry_run: options.dry_run,
147	                interactive,
148	                diagnostic_funnel: options.diagnostic_funnel,
149	                project_root,
150	                base_env,

