56	/// Why a step was skipped at runtime.
57	///
58	/// This lets the workflow layer categorize skips without inspecting
59	/// `StepResult` internals — per-step classification stays in StepManager.
60	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
61	pub(super) enum SkipCategory {
62	    /// Check passed — step is already satisfied.
63	    Satisfied,
64	    /// Dependency was skipped by user, so this step was transitively skipped.
65	    DependencySkipped,
66	    /// User actively declined a prompt (autorun, confirm, sensitive).
67	    UserDeclined,
68	    /// User chose to skip during recovery after a failure.
69	    /// Unlike `UserDeclined`, this does NOT block dependents — the user
70	    /// explicitly chose to continue past the failure.
71	    RecoverySkipped,
72	    /// Other skip reason (generic fallback from engine).
73	    Other,
74	}
