76	/// The action taken by a step during execution, returned to the workflow layer.
77	pub(super) enum StepAction {
78	    /// Step executed successfully.
79	    Completed(StepResult),
80	    /// Step was skipped at runtime, with the reason categorized.
81	    Skipped(StepResult, SkipCategory),
82	    /// Step failed.
83	    Failed(StepResult),
84	    /// Step was blocked (dependency failed, precondition failed, etc.).
85	    Blocked,
86	    /// User chose to abort the workflow.
87	    Aborted(StepResult),
88	}
