541	    /// Handle a blocked step (dependency failed, precondition failed, etc.).
542	    fn handle_block(
543	        &self,
544	        reason: &BlockReason,
545	        step_header_text: &str,
546	        step_pad: &str,
547	        _failed_steps: &HashSet<String>,
548	        event_bus: &mut EventBus,
549	        step_display: &mut dyn StepDisplay,
550	    ) -> Result<StepAction> {
551	        let reason_str = match reason {
552	            BlockReason::DependencyFailed { dependency } => {
553	                event_bus.emit(&BivvyEvent::DependencyBlocked {
554	                    name: self.step_name.to_string(),
555	                    blocked_by: dependency.clone(),
556	                    reason: "dependency_failed".to_string(),
557	                });
558	                "dependency_failed"
559	            }
560	            BlockReason::DependencySkipped { .. } => "dependency_skipped",
561	            BlockReason::PreconditionFailed { .. } => "precondition_failed",
562	            BlockReason::DependencyUnsatisfied { .. } => "dependency_unsatisfied",
563	        };
564	        event_bus.emit(&BivvyEvent::StepDecided {
565	            name: self.step_name.to_string(),
566	            decision: "block".to_string(),
567	            reason: Some(reason_str.to_string()),
568	            trace: None,
569	        });
570	        step_display.message(step_header_text);
571	        step_display.message(&format!(
572	            "{}{}",
573	            step_pad,
574	            StatusKind::Blocked.format(self.theme, &reason.message())
575	        ));
576	
577	        // Every block path — including DependencySkipped, which the workflow
578	        // treats as a transitive skip — emits StepOutcome::Blocked. The
579	        // detail string carries the user-facing reason ("Skipped (dependency
580	        // 'X' skipped)" vs "Blocked (precondition failed: ...)").
581	        event_bus.emit(&BivvyEvent::StepOutcome {
582	            name: self.step_name.to_string(),
583	            outcome: StepOutcomeKind::Blocked,
584	            detail: Some(reason.message()),
585	            duration_ms: None,
586	        });
587	
588	        // For dependency_skipped, return a skip result, not a block
589	        if matches!(reason, BlockReason::DependencySkipped { .. }) {
590	            Ok(StepAction::Skipped(
591	                StepResult::skipped(&self.step.name, CheckResult::passed("Dependency skipped")),
592	                SkipCategory::DependencySkipped,
593	            ))
594	        } else {
595	            Ok(StepAction::Blocked)
596	        }
597	    }
