213	    /// Get a satisfaction record for a step.
214	    ///
215	    /// Checks the runtime layer first, then the persisted layer.
216	    /// Persisted records are validated before being returned — if the evidence
217	    /// is stale or the config/step hash doesn't match, the record is discarded.
218	    pub fn get(
219	        &self,
220	        step: &str,
221	        project_root: &Path,
222	        config_hash: Option<&str>,
223	        step_hash: Option<&str>,
224	    ) -> Option<&SatisfactionRecord> {
225	        // Runtime layer takes precedence — no validation needed (just computed)
226	        if let Some(record) = self.runtime.get(step) {
227	            return Some(record);
228	        }
229	
230	        // Check persisted layer with validation
231	        if let Some(record) = self.persisted.get(step) {
232	            // Structural invalidation: config or step definition changed
233	            if let Some(expected) = config_hash {
234	                if record.config_hash.as_deref() != Some(expected) {
235	                    return None;
236	                }
237	            }
238	            if let Some(expected) = step_hash {
239	                if record.step_hash.as_deref() != Some(expected) {
240	                    return None;
241	                }
242	            }
243	
244	            // Evidence validation
245	            if record.evidence.validate(project_root) {
246	                return Some(record);
247	            }
248	        }
249	
250	        None
251	    }
