263	    /// Check if a step has any record (runtime or persisted, without validation).
264	    pub fn has_record(&self, step: &str) -> bool {
265	        self.runtime.contains_key(step) || self.persisted.contains_key(step)
266	    }
267	
268	    /// Invalidate a specific step's records from both layers.
269	    pub fn invalidate(&mut self, step: &str) {
270	        self.runtime.remove(step);
271	        self.persisted.remove(step);
272	    }
273	
274	    /// Invalidate all records (for `--fresh` mode).
275	    pub fn invalidate_all(&mut self) {
276	        self.runtime.clear();
277	        self.persisted.clear();
278	    }
279	
280	    /// Flush the runtime cache to disk as `satisfaction.json`.
281	    ///
282	    /// Merges runtime records into persisted records (runtime wins on conflict),
283	    /// then writes the combined result to disk using atomic write.
284	    pub fn flush(&mut self) -> std::io::Result<()> {
285	        // Merge runtime into persisted
286	        for (step, record) in &self.runtime {
287	            self.persisted.insert(step.clone(), record.clone());
288	        }
289	
290	        // Ensure parent directory exists
291	        if let Some(parent) = self.path.parent() {
292	            std::fs::create_dir_all(parent)?;
293	        }
294	
295	        // Atomic write: temp file then rename
296	        let content =
297	            serde_json::to_string_pretty(&self.persisted).map_err(std::io::Error::other)?;
298	        let temp_path = self.path.with_extension("json.tmp");
299	        std::fs::write(&temp_path, &content)?;
300	        std::fs::rename(&temp_path, &self.path)?;
301	
302	        Ok(())
303	    }
304	
305	    /// Get the path to the satisfaction.json file.
306	    pub fn path(&self) -> &Path {
307	        &self.path
308	    }
309	
310	    /// Get the number of records in the runtime layer.
311	    pub fn runtime_len(&self) -> usize {
312	        self.runtime.len()
313	    }
314	
315	    /// Get the number of records in the persisted layer.
316	    pub fn persisted_len(&self) -> usize {
317	        self.persisted.len()
318	    }
319	}
