158	    #[test]
159	    fn revalidation_result_variants() {
160	        let unchanged = RevalidationResult::Unchanged;
161	        let updated = RevalidationResult::Updated("new content".to_string());
162	        let failed = RevalidationResult::Failed("network error".to_string());
163	
164	        // Just check we can pattern match
165	        match unchanged {
166	            RevalidationResult::Unchanged => {}
167	            _ => panic!("expected Unchanged"),
168	        }
169	
170	        match updated {
171	            RevalidationResult::Updated(content) => assert_eq!(content, "new content"),
172	            _ => panic!("expected Updated"),
173	        }
174	
175	        match failed {
176	            RevalidationResult::Failed(msg) => assert_eq!(msg, "network error"),
177	            _ => panic!("expected Failed"),
178	        }
179	    }
