218	        let server = MockServer::start();
219	
220	        server.mock(|when, then| {
221	            when.method(GET).path("/template.yml");
222	            then.status(200)
223	                .header("ETag", "\"etag-v2\"")
224	                .body("new content");
225	        });
226	
227	        let temp = TempDir::new().unwrap();
228	        let store = CacheStore::new(temp.path());
229	        let git_dir = temp.path().join("git");
230	        let revalidator = CacheRevalidator::new(&store, git_dir);
231	
232	        // Create an expired cache entry with an old etag
233	        let mut entry = store
234	            .store("http:test", "template", "old content", 0)
235	            .unwrap();
236	        entry.metadata.etag = Some("\"etag-v1\"".to_string());
237	        store.update(&entry).unwrap();
238	
239	        let result = revalidator
240	            .revalidate_etag(&server.url("/template.yml"), &mut entry, 3600)
241	            .unwrap();
242	
243	        match result {
244	            RevalidationResult::Updated(content) => {
245	                assert_eq!(content, "new content");
246	            }
247	            other => panic!("Expected Updated, got {:?}", other),
248	        }
249	
250	        // ETag should be updated
251	        assert_eq!(entry.metadata.etag, Some("\"etag-v2\"".to_string()));
252	        // TTL should be extended
253	        assert!(!entry.is_expired());
254	    }
